INSERT INTO orinuno_remote_source_watermark (
    source_type, last_fetched_at, last_polled_at, last_event_count, last_error
) VALUES (
    #{sourceType}, #{lastFetchedAt}, #{lastPolledAt}, #{lastEventCount}, #{lastError}
)
ON DUPLICATE KEY UPDATE
    last_fetched_at  = COALESCE(VALUES(last_fetched_at), last_fetched_at),
    last_polled_at   = VALUES(last_polled_at),
    last_event_count = VALUES(last_event_count),
    last_error       = VALUES(last_error)
